mapper.select:
SELECT id, ds_id, check_type, check_result, dialect_identified, connection_ok, readonly_ok, dictionary_ok, whitelist_ok, failure_items, error_message, cost_ms, operator_id, create_time FROM t_ds_config_health
AND ds_id = #{dsId}
AND check_type = #{checkType}
ORDER BY create_time DESC, id DESC
